<script>
  import ArcIcon from '../../components/ArcIcon.svelte'
  import { preflightAdminNode, fetchAdminNodeMetrics } from '../../lib/api.js'
  export let data; export let diagnostics = {}; export let diagnosticNode = ''; export let onDiagnostic
  let filter = 'all'
  let builderOpen = false; let host=''; let username='root'; let password=''; let preset='direct'; let checking=false; let preflight=null; let builderError=''
  let selectedNode=null; let metricRange='1h'; let metricSamples=[]; let metricsLoading=false; let metricsError=''
  $: nodes = (data?.remnawave?.nodes || []).filter(node => !/finland lte/i.test(node.name || ''))
  $: edges = data?.remnawave?.lte_edges || []
  $: visible = nodes.filter(node => filter === 'all' || (filter === 'online' ? node.connected : !node.connected))
  const bitRate = value => Number(value || 0) >= 1_000_000 ? `${(Number(value) / 1_000_000).toFixed(1)} Мбит/с` : `${Math.round(Number(value || 0) / 1000)} Кбит/с`
  const byteRate = value => Number(value || 0) >= 1_000_000 ? `${(Number(value) / 1_000_000).toFixed(1)} МБ/с` : `${Math.round(Number(value || 0) / 1000)} КБ/с`
  const pct = value => `${Number(value || 0).toFixed(1)}%`
  const uptime = value => value ? `${Math.floor(Number(value)/86400)} д ${Math.floor(Number(value)%86400/3600)} ч` : '—'
  function points(key){const values=metricSamples.map(item=>Number(item[key]||0));if(!values.length)return '';const max=Math.max(...values,1);return values.map((value,index)=>`${(index/Math.max(1,values.length-1)*600).toFixed(1)},${(145-value/max*130).toFixed(1)}`).join(' ')}
  async function openNode(node, range=metricRange){selectedNode=node;metricRange=range;metricsLoading=true;metricsError='';try{const result=await fetchAdminNodeMetrics(node.address,range);metricSamples=result.samples||[]}catch(error){metricSamples=[];metricsError=error.reason||error.message}finally{metricsLoading=false}}
  async function checkServer(){if(checking)return;checking=true;builderError='';preflight=null;try{preflight=await preflightAdminNode({host:host.trim(),username:username.trim(),password,preset});password=''}catch(error){builderError=error.reason==='ssh_auth_failed'?'SSH не принял логин или пароль.':`Проверка не пройдена: ${error.reason||error.message}`}finally{checking=false}}
</script>

<section class="page" aria-labelledby="nodes-title">
  <header class="page-head"><div><span>ИНФРАСТРУКТУРА</span><h2 id="nodes-title">Ноды и LTE-контур</h2><p>Физические RemnaNode и отдельные CDN-маршруты, которые включаются при глушении.</p></div><button on:click={()=>builderOpen=!builderOpen} aria-expanded={builderOpen} aria-controls="ssh-preflight"><ArcIcon name="plus" size={17}/>{builderOpen?'Закрыть проверку':'Проверить новый сервер'}</button></header>
  {#if builderOpen}<section class="builder" id="ssh-preflight"><header><div><small>SSH-ПРОВЕРКА</small><b>Доступ и сведения о сервере</b></div><em>Без установки и добавления ноды</em></header><p class="scope-note">Проверка только подключается по SSH и читает сведения о системе. Она не устанавливает агент, не создаёт Remnawave Node и не меняет подписки.</p><form on:submit|preventDefault={checkServer} aria-busy={checking}><label>IP или домен<input bind:value={host} autocomplete="off" placeholder="203.0.113.10" required disabled={checking}/></label><label>SSH-пользователь<input bind:value={username} autocomplete="username" required disabled={checking}/></label><label>SSH-пароль<input bind:value={password} type="password" autocomplete="new-password" required disabled={checking}/></label><label>Профиль проверки<select bind:value={preset} disabled={checking}><option value="direct">Обычная нода</option><option value="bridge">Нода + мост</option><option value="warp">Нода + WARP</option></select></label><button disabled={checking || !host.trim() || !username.trim() || !password}>{checking?'Проверяем SSH…':'Проверить SSH-доступ'}</button></form><div aria-live="polite">{#if builderError}<p class="builder-error" role="alert">{builderError}</p>{/if}{#if preflight}<div class="preflight"><i>✓</i><span><b>SSH-доступ подтверждён</b><small>{preflight.system} · {(preflight.addresses || []).join(', ')}</small></span><em>{preflight.preset}</em></div><p class="next">Проверка завершена. Установка и ввод в эксплуатацию выполняются отдельным операционным процессом с production gate.</p>{/if}</div></section>{/if}
  {#if selectedNode}<section class="node-detail">
    <header><div><small>НОДЫ / {selectedNode.name}</small><h2>{selectedNode.country_code || '—'} · {selectedNode.name}</h2><p>{selectedNode.address} · {selectedNode.connected ? 'Remnawave в сети' : 'нет связи'} · uptime {uptime(selectedNode.xray_uptime_seconds)}</p></div><button on:click={()=>selectedNode=null} aria-label={`Закрыть телеметрию ноды ${selectedNode.name}`}>Закрыть</button></header>
    <nav aria-label="Период телеметрии">{#each [['15m','15 мин'],['1h','1 час'],['6h','6 часов'],['24h','24 часа'],['7d','7 дней']] as range}<button class:active={metricRange===range[0]} aria-pressed={metricRange===range[0]} disabled={metricsLoading} on:click={()=>openNode(selectedNode,range[0])}>{range[1]}</button>{/each}</nav>
    {#if metricsLoading}<p class="detail-state">Загружаем телеметрию…</p>{:else if metricsError}<p class="detail-state error">Метрики недоступны: {metricsError}</p>{:else if !metricSamples.length}<p class="detail-state">Для этой ноды ещё нет agent samples. Карточка не подменяет их данными Remnawave.</p>{:else}<div class="metric-grid">
      <article><header><b>CPU</b><span>{pct(metricSamples.at(-1)?.cpu_pct)}</span></header><svg viewBox="0 0 600 160" preserveAspectRatio="none" role="img" aria-label={`Загрузка CPU за ${metricRange}`}><polyline points={points('cpu_pct')}/></svg></article>
      <article class="memory"><header><b>Память</b><span>{pct(metricSamples.at(-1)?.mem_pct)}</span></header><svg viewBox="0 0 600 160" preserveAspectRatio="none" role="img" aria-label={`Использование памяти за ${metricRange}`}><polyline points={points('mem_pct')}/></svg></article>
      <article class="network"><header><b>Сеть ↓</b><span>{bitRate(metricSamples.at(-1)?.net_rx_bps)}</span></header><svg viewBox="0 0 600 160" preserveAspectRatio="none" role="img" aria-label={`Входящая скорость за ${metricRange}`}><polyline points={points('net_rx_bps')}/></svg></article>
      <article class="network up"><header><b>Сеть ↑</b><span>{bitRate(metricSamples.at(-1)?.net_tx_bps)}</span></header><svg viewBox="0 0 600 160" preserveAspectRatio="none" role="img" aria-label={`Исходящая скорость за ${metricRange}`}><polyline points={points('net_tx_bps')}/></svg></article>
    </div>{/if}
    <div class="service-row"><span class:ok={selectedNode.connected}>Remnawave Node <b>{selectedNode.connected?'работает':'нет связи'}</b></span><span class:ok={(selectedNode.inbounds||[]).length>0}>Xray Core <b>{(selectedNode.inbounds||[]).length} inbound</b></span><span class:ok={metricSamples.length>0}>Arc agent <b>{metricSamples.length?'передаёт метрики':'нет samples'}</b></span></div>
  </section>{/if}
  <section class="edge-board" aria-label="LTE маршруты">
    <header><div><small>АВАРИЙНЫЙ КОНТУР</small><b>CDN → origin → XHTTP</b></div><em>{edges.filter(edge => edge.healthy).length}/{edges.length} готовы</em></header>
    <div class="edge-grid">{#if edges.length}{#each edges as edge}<article class:off={!edge.healthy}>
      <div class="edge-title"><i>{edge.country_code}</i><span><b>{edge.name}</b><small>{edge.profile_name}</small></span><em>{edge.healthy ? 'READY' : 'DEGRADED'}</em></div>
      <div class="rail"><span>{edge.public_host}</span><i>CDN</i><span>{edge.origin || 'origin не найден'}</span><i>:{edge.port}</i><span>{String(edge.network || 'xhttp').toUpperCase()}</span></div>
      <dl><div><dt>Inbound</dt><dd>{edge.inbound_active ? 'активен' : 'не найден'}</dd></div><div><dt>Путь</dt><dd>{edge.path}</dd></div><div><dt>Учёт трафика</dt><dd>отдельный LTE</dd></div><div><dt>Онлайн на origin</dt><dd>{edge.users_online || 0}</dd></div></dl>
    </article>{/each}{:else}<div class="empty wide"><b>LTE-маршруты не настроены</b><p>Экран не подменяет отсутствующий аварийный контур тестовыми данными.</p></div>{/if}</div>
  </section>
  <nav aria-label="Фильтр нод"><button class:active={filter==='all'} aria-pressed={filter==='all'} on:click={()=>filter='all'}>Все <i>{nodes.length}</i></button><button class:active={filter==='online'} aria-pressed={filter==='online'} on:click={()=>filter='online'}>Онлайн <i>{nodes.filter(n=>n.connected).length}</i></button><button class:active={filter==='problems'} aria-pressed={filter==='problems'} on:click={()=>filter='problems'}>Проблемы <i>{nodes.filter(n=>!n.connected).length}</i></button></nav>
  <div class="nodes" aria-busy={Boolean(diagnosticNode)}>{#if visible.length}{#each visible as node}<article class:off={!node.connected} class:selected={selectedNode?.uuid === node.uuid}>
    <header><i>{node.country_code || '—'}</i><span><b>{node.name}</b><small>{node.address}</small></span><em>{node.connected?'ONLINE':'OFFLINE'}</em></header>
    <div class="stats"><span><small>ОНЛАЙН</small><b>{node.users_online||0}</b></span><span><small>ТРАФИК</small><b>{node.traffic_used_gb||0} ГБ</b></span><span><small>RAM</small><b>{node.memory_used_pct||0}%</b></span><span><small>СЕТЬ</small><b>{byteRate((node.rx_bps||0)+(node.tx_bps||0))}</b></span></div>
    <div class="inbounds">{#each node.inbounds||[] as inbound}<span>{String(inbound.network||inbound.type||'').toUpperCase()} <b>:{inbound.port}</b><small>{inbound.tag}</small></span>{/each}</div>
    {#if diagnostics[node.uuid]}<p class:good={diagnostics[node.uuid].ok}>{diagnostics[node.uuid].ok ? `Тест пройден за ${diagnostics[node.uuid].duration_ms} мс` : `Ошибка: ${diagnostics[node.uuid].error}`}</p>{/if}
    <div class="node-actions"><button on:click={()=>openNode(node)} aria-expanded={selectedNode?.uuid === node.uuid}>{selectedNode?.uuid === node.uuid ? 'Телеметрия открыта' : 'Открыть телеметрию'}</button><button class="test" disabled={Boolean(diagnosticNode)} on:click={()=>onDiagnostic?.(node)}><ArcIcon name="pulse" size={16}/>{diagnosticNode===node.uuid?'Проверяем…':diagnosticNode?'Идёт другой тест':'Глубокий тест'}</button></div>
  </article>{/each}{:else}<div class="empty"><b>{nodes.length ? 'В этом фильтре нод нет' : 'Ноды не обнаружены'}</b><p>{nodes.length ? 'Выберите другой фильтр.' : 'Проверьте Remnawave и обновите данные панели.'}</p></div>{/if}</div>
</section>

<style>
.page{display:grid;gap:20px}.page>header span,.edge-board small{color:#80c9f4;font-size:10px;font-weight:900;letter-spacing:.15em}.page h2{margin:8px 0 5px;font-size:30px}.page p,.page>header p{margin:0;color:#7890a5}.edge-board{overflow:hidden;border:1px solid rgba(120,210,255,.16);border-radius:24px;background:linear-gradient(135deg,#0b1622,#101c29)}.edge-board>header{display:flex;align-items:center;justify-content:space-between;padding:18px 20px;border-bottom:1px solid rgba(255,255,255,.06)}.edge-board>header div{display:grid;gap:4px}.edge-board>header em{color:#78e1b4;font-size:11px;font-style:normal}.edge-grid{display:grid;grid-template-columns:1fr 1fr}.edge-grid article{padding:20px}.edge-grid article+article{border-left:1px solid rgba(255,255,255,.06)}.edge-grid article.off{background:rgba(255,100,110,.035)}.edge-title{display:flex;align-items:center;gap:11px}.edge-title>i,.nodes header>i{display:grid;width:44px;height:44px;place-items:center;border-radius:15px;background:#15314a;color:#9bd9ff;font-style:normal;font-weight:900}.edge-title span{display:grid;flex:1}.edge-title small{color:#7890a5;letter-spacing:0}.edge-title em,.nodes header em{padding:7px 9px;border-radius:10px;background:#123127;color:#75ddb0;font-size:9px;font-style:normal;font-weight:900}.off .edge-title em,.nodes .off header em{background:#351d26;color:#ff9c9c}.rail{display:grid;grid-template-columns:minmax(0,1fr) auto minmax(0,1fr) auto auto;align-items:center;gap:7px;margin:18px 0;padding:11px;border-radius:14px;background:#08111a;color:#afc5d7;font:10px ui-monospace,SFMono-Regular,monospace}.rail span{overflow:hidden;text-overflow:ellipsis}.rail i{color:#5e7d95;font-style:normal}.edge-grid dl{display:grid;grid-template-columns:1fr 1fr;gap:7px;margin:0}.edge-grid dl div{padding:9px;border-radius:11px;background:rgba(255,255,255,.025)}dt{color:#637b8e;font-size:9px}dd{margin:4px 0 0;color:#dcecf7;font-size:11px}.page>nav{display:flex;gap:7px}.page>nav button{padding:10px 14px;border:0;border-radius:13px;background:#101b29;color:#7890a5}.page>nav button.active{background:#9bd9ff;color:#07111d}.page>nav i{margin-left:5px;font-style:normal}.nodes{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:13px}.nodes>article{padding:21px;border:1px solid rgba(155,217,255,.1);border-radius:24px;background:linear-gradient(150deg,#101b29,#09121d)}.nodes>article.off{opacity:.72;border-color:rgba(255,121,121,.2)}.nodes article>header{display:flex;align-items:center;gap:11px}.nodes header>span{display:flex;flex:1;flex-direction:column}.nodes header small{color:#7890a5}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:20px 0}.stats span{padding:12px;border-radius:15px;background:#0d1825}.stats small,.stats b{display:block}.stats small{color:#6f879b;font-size:8px}.stats b{margin-top:7px}.inbounds{display:flex;flex-wrap:wrap;gap:6px}.inbounds span{display:grid;padding:7px 9px;border-radius:11px;background:#0d1825;color:#93aabd;font-size:10px}.inbounds b{color:#9bd9ff}.inbounds small{max-width:190px;overflow:hidden;color:#526b7f;text-overflow:ellipsis}.test{display:flex;width:100%;justify-content:center;gap:8px;margin-top:18px;padding:12px;border:1px solid rgba(155,217,255,.14);border-radius:14px;background:#14283a;color:#bde7ff;font-weight:900}.nodes p.good{color:#75d8aa}@media(max-width:950px){.edge-grid,.nodes{grid-template-columns:1fr}.edge-grid article+article{border-top:1px solid rgba(255,255,255,.06);border-left:0}.stats{grid-template-columns:1fr 1fr}.rail{grid-template-columns:1fr auto}.rail i{display:none}}
.page-head{display:flex;align-items:end;justify-content:space-between;gap:20px}.page-head>button{display:flex;align-items:center;gap:8px;min-height:44px;padding:0 16px;border:1px solid #3a292d;border-radius:13px;background:#211719;color:#f1d9dd;font-weight:800}.builder{padding:20px;border:1px solid #38282c;border-radius:22px;background:#151012}.builder>header{display:flex;align-items:center;justify-content:space-between}.builder>header div{display:grid;gap:4px}.builder small{color:#97888c}.builder>header em{color:#d5a0a8;font-size:10px;font-style:normal}.builder form{display:grid;grid-template-columns:1.2fr .7fr 1fr 1fr auto;gap:9px;margin-top:17px}.builder label{display:grid;gap:6px;color:#96878b;font-size:9px}.builder input,.builder select,.builder form button{box-sizing:border-box;min-height:44px;border:1px solid #34272a;border-radius:12px;background:#0f0b0c;color:#f3eaec;padding:0 12px}.builder form button{align-self:end;background:#e1a0a9;color:#1b1113;font-weight:900}.builder-error{margin-top:12px!important;color:#ff9ca7!important}.preflight{display:flex;align-items:center;gap:12px;margin-top:14px;padding:13px;border-radius:14px;background:#17201b}.preflight>i{display:grid;width:30px;height:30px;place-items:center;border-radius:50%;background:#24402f;color:#86d9a7;font-style:normal}.preflight span{display:grid;flex:1}.preflight em{color:#86d9a7;font-size:10px;font-style:normal}.next{margin-top:10px!important;font-size:11px}@media(max-width:1050px){.builder form{grid-template-columns:1fr 1fr}.builder form button{grid-column:1/3}}@media(max-width:650px){.page-head{align-items:stretch;flex-direction:column}.builder form{grid-template-columns:1fr}.builder form button{grid-column:auto}}
.page-head>button{border-color:#274057;background:#14283a;color:#bde7ff}.builder{border-color:#23394c;background:#101821}.builder small{color:#70879b}.builder>header em{color:#80c9f4}.builder label{color:#7890a5}.builder input,.builder select,.builder form button{border-color:#24394b;background:#0b121b;color:#edf7ff}.builder form button{background:#9bd9ff;color:#07111d}
.node-detail{padding:24px;border:1px solid #26394a;border-radius:26px;background:#0b121b}.node-detail>header{display:flex;align-items:start;justify-content:space-between;gap:20px}.node-detail>header small{color:#71899d;font-size:9px;font-weight:900;letter-spacing:.12em}.node-detail>header h2{margin:8px 0 5px}.node-detail>header button{padding:9px 13px;border:1px solid #2a3e50;border-radius:12px;background:#101b28;color:#a7bdce}.node-detail>nav{display:flex;gap:5px;margin:22px 0}.node-detail>nav button{padding:9px 13px;border:0;border-radius:11px;background:#121d29;color:#71899c}.node-detail>nav button.active{background:#9bd9ff;color:#07111d}.metric-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.metric-grid article{overflow:hidden;padding:16px;border:1px solid #203243;border-radius:19px;background:#0d1722}.metric-grid article>header{display:flex;justify-content:space-between}.metric-grid article>header span{color:#8da7bb;font-family:monospace}.metric-grid svg{display:block;width:100%;height:150px;margin-top:10px;background-image:linear-gradient(#ffffff08 1px,transparent 1px);background-size:100% 37px}.metric-grid polyline{fill:none;stroke:#f09aa5;stroke-width:3;vector-effect:non-scaling-stroke}.metric-grid .memory polyline{stroke:#76bfff}.metric-grid .network polyline{stroke:#e8b957}.metric-grid .up polyline{stroke:#69d4ae}.detail-state{display:grid;min-height:190px;place-items:center;border:1px dashed #26394a;border-radius:18px}.detail-state.error{color:#ff9ca7}.service-row{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:12px}.service-row span{display:flex;justify-content:space-between;padding:12px;border-radius:13px;background:#21161b;color:#d19aa3;font-size:10px}.service-row span.ok{background:#13241d;color:#78d6aa}.service-row b{font-weight:500}.node-actions{display:grid;grid-template-columns:.75fr 1.25fr;gap:7px;margin-top:18px}.node-actions button{min-height:42px;border:1px solid rgba(155,217,255,.14);border-radius:14px;background:#0e1b28;color:#94b5cd;font-weight:900}.node-actions .test{margin:0}@media(max-width:760px){.metric-grid,.service-row{grid-template-columns:1fr}.node-detail{padding:17px}.node-detail>header{flex-direction:column}}
.page,.builder,.node-detail,.edge-board,.nodes{min-width:0}.scope-note{margin-top:12px!important;font-size:11px}.empty{display:grid;min-height:130px;place-content:center;padding:20px;border:1px dashed #26394a;border-radius:18px;text-align:center}.empty.wide{grid-column:1/-1;margin:18px}.empty b{margin-bottom:6px}.nodes>article.selected{border-color:#4b7797;box-shadow:0 0 0 1px #4b779733}.page button{cursor:pointer}.page button:disabled{cursor:not-allowed;opacity:.48}.page button:focus-visible,.builder input:focus-visible,.builder select:focus-visible{outline:2px solid #9bd9ff;outline-offset:2px}@media(max-width:560px){.edge-board>header{align-items:flex-start;gap:8px}.rail{display:flex;align-items:flex-start;flex-direction:column;overflow-wrap:anywhere}.rail i{display:block}.node-actions{grid-template-columns:1fr}.nodes>article{padding:16px}.stats{grid-template-columns:1fr 1fr}.builder>header{align-items:flex-start;gap:8px;flex-direction:column}.preflight{align-items:flex-start;flex-wrap:wrap}.preflight em{margin-left:42px}}
</style>
